def run_all(
    block_ids: Sequence[str],
    record: Mapping[str, Any],
    context: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Call every declared block in order; the first refusal ends the run.

    Returns {"ok": True, "blocks": {id: result}} or the refusal.
    """
    ctx = dict(context or {})
    out: Dict[str, Any] = {}
    for block_id in block_ids:
        answer = call_block(block_id, record, ctx)
        if is_failure(answer):
            failure = refused(block_id, answer)
            failure["blocks"] = out
            return failure
        out[block_id] = block_result(answer)
    return {"ok": True, "blocks": out}


