def canonical_address(host: str):
    """The IP a host literal denotes, or None when it is not an IP literal.

    Covers the spellings that defeat a naive string check: a trailing dot
    (the DNS root: "127.0.0.1."), an integer or hex IPv4
    ("2130706433", "0x7f000001"), and the short dotted forms inet_aton
    accepts ("127.1", "10.1"). A real hostname returns None -- resolving it
    is the caller's job, and guard_outbound refuses anything it cannot prove
    is public.
    """
    import re as _re
    import socket

    name = str(host or "").strip().strip("[]").strip().lower().rstrip(".")
    if not name:
        return None
    if name in ("localhost", "localhost.localdomain", "ip6-localhost"):
        return ipaddress.ip_address("127.0.0.1")
    try:
        return ipaddress.ip_address(name)
    except ValueError:
        pass
    if _re.match(r"^(0[xX][0-9a-fA-F]+|[0-9]+)$", name):
        try:
            return ipaddress.ip_address(int(name, 0))
        except ValueError:
            return None
    try:
        return ipaddress.ip_address(socket.inet_aton(name))
    except (OSError, ValueError):
        return None


def is_private_host(host: str) -> bool:
    """True for loopback, link-local, private and reserved addresses.

    A host that is not an IP literal is NOT proven public: guard_outbound
    refuses it rather than letting an unverified name through. A caller that
    has resolved the name passes the resolved address here instead.
    """
    name = str(host or "").strip()
    if not name:
        return True
    address = canonical_address(name)
    if address is None:
        return name.strip().strip("[]").lower().rstrip(".") in (
            "localhost",
            "localhost.localdomain",
            "ip6-localhost",
        )
    return bool(
        address.is_private
        or address.is_loopback
        or address.is_link_local
        or address.is_reserved
        or address.is_multicast
        or address.is_unspecified
    )


def guard_outbound(url: str, *, allowed_hosts: Optional[Sequence[str]] = None) -> str:
    """Validate a caller-controlled URL before any egress. Returns the URL.

    A non-http(s) scheme, a private/loopback/reserved host, or a host outside
    the operator's allow-list is refused by name -- never fetched and then
    filtered.
    """
    raw = str(url or "").strip()
    parsed = urlparse(raw)
    if parsed.scheme not in ("http", "https"):
        raise EgressRefused("egress_refused: scheme %r not allowed" % parsed.scheme)
    if parsed.username or parsed.password:
        # http://user@host hides the real destination from a reader.
        raise EgressRefused("egress_refused: credentials in the URL are not accepted")
    host = parsed.hostname or ""
    if not host:
        raise EgressRefused("egress_refused: no host in URL")
    if is_private_host(host):
        raise EgressRefused(
            "egress_refused: %s is a private, loopback or reserved address" % host
        )
    allowed = [str(item).strip().lower() for item in (allowed_hosts or ()) if str(item).strip()]
    if allowed and host.lower() not in allowed:
        raise EgressRefused(
            "egress_refused: %s is not in the operator's allow-list" % host
        )
    return raw


